type ValidationError struct{ Field string }
func (e *ValidationError) Error() string { return e.Field }

func validate(name string) error {
    var verr *ValidationError        // nil-указатель
    if name == "" {
        verr = &ValidationError{Field: "name"}
    }
    return verr                      // ловушка!
}

err := validate("Аня")
fmt.Println(err == nil)              // false
fmt.Printf("%T %v\n", err, err)      // *main.ValidationError <nil>

func validate(name string) error {
    if name == "" {
        return &ValidationError{Field: "name"}
    }
    return nil                       // настоящий nil-интерфейс
}
